/bin/zsh -lc "python3 -c 'import csv,datetime,ipaddress,collections; rows=list(csv.DictReader(open(\"Semana12/logs_sinteticos.csv\",newline=\"\"))); data=[(n,datetime.datetime.fromisoformat(r[\"timestamp\"]),r) for n,r in enumerate(rows,2)]; [ipaddress.ip_address(r[\"ip\"]) for _,_,r in data]; data.sort(key=lambda x:x[1]); print(\"Registros válidos:\",len(data)); groups=collections.defaultdict(list); [groups[tuple(r.items())].append(n) for n,_,r in data]; print(\"Filas idénticas:\",[v for v in groups.values() if len(v)>1]); failed=[x for x in data if x[2][\"event\"]==\"login\" and x[2][\"result\"]==\"failed\"]; brute=set(); spray=set(); span=datetime.timedelta(minutes=5)
for n,t,r in failed:
 w=[x for x in failed if t<=x[1]<=t+span and x[2][\"ip\"]==r[\"ip\"]]; b=tuple(x[0] for x in w if x[2][\"user\"]==r[\"user\"])
 if len(b)>=6: brute.add(b)
 if len(set(x[2][\"user\"] for x in w))>=5: spray.add(tuple(x[0] for x in w))
print(\"Ventanas fuerza bruta:\",sorted(brute)); print(\"Ventanas spraying:\",sorted(spray)); print(\"Token, filas:\",[n for n,_,r in data if \"token=\" in r[\"detail\"]]); print(\"Cambios sin aprobación, filas:\",[n for n,_,r in data if r[\"event\"]==\"role_change\" and r[\"result\"]==\"success\" and \"approved=false\" in r[\"detail\"]])'"

